using GameTranslator.Core;
namespace GameTranslator.Core.Tests;
public class ReadingAreaTests_Stability
{
 [Fact]public void DuplicateGeometryDoesNotCreateAnotherReaderButDifferentGeometryRemains(){var a=ReadingArea.Phone();Assert.Equal(2,ReadingArea.Unique([a,a with{Id="duplicate"},a with{Id="custom",Source=new(.2,.6,.2,.6)}]).Count);}
 [Fact]public void ImportedDuplicateCardsAreExplainedInsteadOfRunTwice(){var a=ReadingArea.Menu();var dialogue=new ReadingArea("dialogue","Dialogue",ReadingAreaKind.Dialogue,new(),new());Assert.Throws<ArgumentException>(()=>ReadingLayout.Import(new ReadingLayout(1,[dialogue,a,a with{Id="duplicate"}]).Export()));}
 [Fact]public void LargeOcrFrameFitsLimitWithoutLosingGeometry(){var f=Frame.Blank(3200,100);f.Pixels[0]=44;var fit=f.Fit(1600);Assert.Equal(1600,fit.Width);Assert.Equal(50,fit.Height);Assert.Same(f,f.Fit(4000));}
 [Fact]public void SettingsPageRetainsBothColumnsAndParagraphs(){var reading=new Reading([new("SETTINGS",new(.03,.03,.15,.08)),new("Audio",new(.05,.3,.25,.35)),new("Adjust the game sound level.",new(.55,.3,.95,.4))]);Assert.Equal(3,MenuReading.Select(Frame.Blank(100,100),reading).Lines.Count);}
 [Fact]public void MapKeepsMissionCardAndControlsButDropsStreetNames(){var frame=Frame.Blank(200,120);Array.Fill(frame.Pixels,(byte)230);for(int y=20;y<50;y++)for(int x=10;x<90;x++){int i=y*frame.Stride+x*4;frame.Pixels[i]=30;frame.Pixels[i+1]=30;frame.Pixels[i+2]=30;}
  var reading=new Reading([new("MAP",new(.4,.03,.5,.08)),new("BRIEF",new(.6,.03,.7,.08)),new("COMING HOME",new(.07,.2,.4,.3)),new("Little York Village",new(.5,.5,.8,.6)),new("Saltpon",new(.2,.6,.4,.65))]);var selected=MenuReading.Select(frame,reading);Assert.Contains(selected.Lines,l=>l.Text=="COMING HOME");Assert.DoesNotContain(selected.Lines,l=>l.Text=="Little York Village"||l.Text=="Saltpon");}
 [Fact]public void JoinedTopNavigationIsRecognizedAsMapAndStreetsStillExcluded(){var f=Frame.Blank(200,100);Array.Fill(f.Pixels,(byte)230);var r=new Reading([new("JASON & LUCIA MAP BRIEF PROGRESS",new(.2,.02,.8,.08)),new("Little Village",new(.2,.4,.4,.45))]);var selected=MenuReading.Select(f,r);Assert.Single(selected.Lines);Assert.StartsWith("JASON",selected.Text);}
 [Fact]public void ControllerHintsKeepOnlyButtonsActuallyPresentInTheSource(){Assert.True(ArabicOutputQuality.Accepts("Press X to select","اضغط X للاختيار"));Assert.True(ArabicOutputQuality.Accepts("BACK B","رجوع B"));Assert.False(ArabicOutputQuality.Accepts("A man is here","A رجل هنا"));Assert.False(ArabicOutputQuality.Accepts("Press X to select","اضغط B للاختيار"));Assert.False(ArabicOutputQuality.Accepts("Press X to select","اضغط select للاختيار"));}
 [Fact]public void GameplayDialogueIsNotTreatedAsPauseMenu(){Assert.Empty(MenuReading.Select(Frame.Blank(100,100),Reading.FromText("Jason: We need to leave now.")).Lines);}
 [Fact]public void DimPhoneAndSeparatedLightPartsCanBeFound(){var f=Frame.Blank(600,600);Fill(f,300,50,170,160,130);Fill(f,300,260,170,280,130);var box=SpatialText.FindPhone(f);Assert.NotNull(box);Assert.True(box!.Bottom-box.Top>.7);}
 [Fact]public async Task NoGeometryFallsBackToVisibleArabicInsteadOfBlankPanel(){long time=0;using var session=new ReadingAreaSession([ReadingArea.Menu() with{AutoDetect=false}],()=>new PlainReader(),new Immediate(),()=>time);var shown=new TaskCompletionSource<AreaCaption>(TaskCreationOptions.RunContinuationsAsynchronously);session.Caption+=c=>shown.TrySetResult(c);await session.ProcessAsync(Frame.Blank(200,100));time=500;await session.ProcessAsync(Frame.Blank(200,100));var value=await shown.Task.WaitAsync(TimeSpan.FromSeconds(3));Assert.Null(value.Panel);Assert.Equal("نص عربي واضح.",value.Text);}
 [Fact]public async Task ChangedCellDoesNotDiscardUnchangedCellsOrShowOldTextInNewCell(){long time=0;var reader=new ChangingReader();var engine=new Waiting();using var session=new ReadingAreaSession([ReadingArea.Menu() with{AutoDetect=false}],()=>reader,engine,()=>time);var shown=new TaskCompletionSource<AreaCaption>(TaskCreationOptions.RunContinuationsAsynchronously);session.Caption+=c=>shown.TrySetResult(c);var f=Frame.Blank(200,100);await session.ProcessAsync(f);time=500;await session.ProcessAsync(f);await engine.Started.Task.WaitAsync(TimeSpan.FromSeconds(3));reader.Second="A completely different message now";time=1000;await session.ProcessAsync(f);engine.Finish.TrySetResult();var value=await shown.Task.WaitAsync(TimeSpan.FromSeconds(3));Assert.NotNull(value.Panel);Assert.Equal("نص عربي واضح.",value.Panel!.Cells[0].Text);Assert.Empty(value.Panel.Cells[1].Text);}
 private sealed class PlainReader:ITextReader{public string Read(Frame f)=>"A complete message.";}
 private sealed class ChangingReader:ITextReader{public string Second="Second message";public string Read(Frame f)=>"";public Reading ReadSpatial(Frame f)=>new([new("First message",new(.1,.1,.6,.2)),new(Second,new(.1,.6,.8,.7))]);}
 private sealed class Immediate:ITextTranslator{public Task<string> TranslateAsync(string s,CancellationToken t=default)=>Task.FromResult("نص عربي واضح.");}
 private sealed class Waiting:ITextTranslator{public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously),Finish=new(TaskCreationOptions.RunContinuationsAsynchronously);public async Task<string> TranslateAsync(string s,CancellationToken t=default){Started.TrySetResult();await Finish.Task;return "نص عربي واضح.";}}
 private static void Fill(Frame f,int x,int y,int w,int h,byte c){for(int yy=y;yy<y+h;yy++)for(int xx=x;xx<x+w;xx++){int i=yy*f.Stride+xx*4;f.Pixels[i]=f.Pixels[i+1]=f.Pixels[i+2]=c;f.Pixels[i+3]=255;}}
}
